import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.CLpArHBg.js";const n="/Cnblogs-Theme-SimpleMemory/v2.1/dist/images/codespaces/codespaces_01.jpg",p="/Cnblogs-Theme-SimpleMemory/v2.1/dist/images/codespaces/codespaces_03.png",m=JSON.parse('{"title":"调试开发","description":"","frontmatter":{},"headers":[],"relativePath":"guide/codespaces.md","filePath":"guide/codespaces.md","lastUpdated":1692862703000}'),l={name:"guide/codespaces.md"};function h(r,s,d,o,c,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="调试开发" tabindex="-1">调试开发 <a class="header-anchor" href="#调试开发" aria-label="Permalink to &quot;调试开发&quot;">​</a></h1><p>需要 Node.js ≥ 20.9.0 和 npm。以下命令在仓库根目录执行。</p><h2 id="本地构建" tabindex="-1">本地构建 <a class="header-anchor" href="#本地构建" aria-label="Permalink to &quot;本地构建&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>构建结果位于 <code>dist/</code>，资源服务默认使用 3100 端口。这个服务只提供插件资源，不包含博客园页面。</p><p>将博客园侧边栏公告中的插件地址临时换成可公开访问的 <strong>HTTPS 调试地址</strong>。HTTPS 博客页面可能阻止 HTTP 本地资源，不能直接把任意本地地址当作远程调试地址。</p><p>每次修改后执行 <code>npm run build</code>，再刷新博客。改动基础样式时，同步更新后台「页面定制 CSS」中的内容。调试结束后恢复正式版本的 CSS 和脚本地址。</p><h2 id="使用-codespaces" tabindex="-1">使用 Codespaces <a class="header-anchor" href="#使用-codespaces" aria-label="Permalink to &quot;使用 Codespaces&quot;">​</a></h2><p>该方式由 <a href="https://github.com/fzxiang" target="_blank" rel="noreferrer">fzxiang</a> 提供。</p><ol><li>在自己的 fork 中创建 Codespace。</li><li>打开终端，执行上面的依赖安装、测试、构建和启动命令。</li><li>在端口面板找到 3100 端口，将可见性设为 <code>Public</code>，以便博客页面无需登录即可加载资源。</li><li>复制该端口的 HTTPS 地址，确认可以访问其中的 <code>simpleMemory.js</code>。</li><li>临时替换博客的插件地址，例如：</li></ol><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://你的-codespace-名称-3100.app.github.dev/simpleMemory.js&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>只公开用于调试插件资源的端口。调试结束后停止资源服务并恢复博客配置。Codespaces 的额度和收费以自己的 GitHub 账户页面为准。</p><p><img src="`+n+'" alt="Codespaces 创建入口"></p><p><img src="'+p+'" alt="端口可见性设置"></p><h2 id="使用-jsdelivr" tabindex="-1">使用 jsDelivr <a class="header-anchor" href="#使用-jsdelivr" aria-label="Permalink to &quot;使用 jsDelivr&quot;">​</a></h2><p>也可以将构建结果提交到自己的公开 fork，通过 commit SHA 加载固定版本。修改源码后需要重新构建并提交 <code>dist/</code>，仅提交源码不会改变插件文件。</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://cdn.jsdelivr.net/gh/你的用户名/Cnblogs-Theme-SimpleMemory@COMMIT_SHA/dist/simpleMemory.js&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>将用户名和 <code>COMMIT_SHA</code> 换成自己的值。CDN 有缓存，频繁调试时优先使用自己的资源服务。</p><h2 id="修改文档" tabindex="-1">修改文档 <a class="header-anchor" href="#修改文档" aria-label="Permalink to &quot;修改文档&quot;">​</a></h2><p>文档的安装、检查和发布目录说明见<a href="./documentation.html">文档维护</a>。</p>',20)])])}const u=i(l,[["render",h]]);export{m as __pageData,u as default};
